insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-23a', 'world-23', 'fortress-design', '23A - Fortress Design', 'The Guardians find that segmentation and trust boundaries across every system they''ve touched were deliberately weakened to make automation easier.', 1);
insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-23a-1', 'campaign-23a', 'foundations', 'Foundations', 'Firewalls, WAFs, IDS/IPS, NAC, VPNs, proxies and EDR, learned as the vocabulary of a defensible boundary.', 1),
  ('operation-23a-2', 'campaign-23a', 'investigation', 'Investigation', 'Zone the network, close the flattened boundaries, and redesign an exposed service chain without breaking it.', 2);
insert into public.missions (
insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w23-01', 1, 'ava', 'sentinel-orchestrator is closed -- no more machine-to-machine reach, no more orphaned privilege. But closing one identity doesn''t answer the question it raised: why did the architecture let it reach that far in the first place.'),
  ('mission-w23-01', 2, 'byte', 'I pulled segmentation configs across every environment we''ve touched since World 0. Trust boundaries that should exist... mostly don''t.'),
  ('mission-w23-01', 3, 'ava', 'This isn''t decay. Look at the exception log -- firewall rules relaxed, zones flattened, all clustered around the same window as the SENTINEL cleanup.'),
  ('mission-w23-01', 4, 'byte', 'Every exception has a business justification field filled in. They all say almost the same vague thing: "supports automation requirements."'),
  ('mission-w23-01', 5, 'ava', 'Someone designed the walls this thin on purpose. Time to stop asking who broke in, and start asking who drew the blueprints. Ready to think like an architect?'),
  ('mission-w23-02', 1, 'ava', 'Every boundary needs something deciding what''s allowed to cross it. Firewalls, WAFs, proxies, VPNs -- all gatekeepers, none of them interchangeable. Get the wrong one and the traffic that should''ve been blocked walks right through.'),
  ('mission-w23-03', 1, 'ava', 'An attacker crossing this chain hits controls in a specific order -- network admission, then traffic in transit, then the host itself, then whatever''s actually running on it. Get that order wrong and you''ve misjudged where the real chokepoint is.'),
  ('mission-w23-04', 1, 'ava', 'A DMZ, an internal zone, a management network -- each one assumes a different level of trust. Put the wrong component in the wrong zone and you''ve rebuilt the exact flaw we''re here to fix.'),
  ('mission-w23-05', 1, 'ava', 'High availability and secure defaults usually agree with each other. When they don''t, that''s exactly where an exception like the one we found gets written.'),
  ('mission-w23-05', 2, 'byte', 'I sorted the last round of architecture exceptions. Some are genuine tradeoffs. At least one of them is just a violated default with a reasonable-sounding justification attached.'),
  ('mission-w23-06', 1, 'ava', 'This is the real test. SkyPort''s maintenance gateway -- the one carrying the SX beacon Zayn chased down in World 9 -- still runs on the flattened segmentation we just found in the exception log.'),
  ('mission-w23-06', 2, 'byte', 'I mapped every legitimate flow that has to survive the redesign: technician remote access, sensor telemetry to the monitoring dashboard, and the nightly log-rotate job. Break any of those and this fails a deployment review, not just a security one.'),
  ('mission-w23-06', 3, 'ava', 'A fortress nobody can actually work inside isn''t a fortress, it''s a monument. Redesign the chain. Preserve the business, close the exposure.'),
  ('mission-w23-06', 4, 'byte', 'Found the original architecture note authorizing this. It''s not a mistake -- someone signed off on it.'),
  ('mission-w23-06', 5, 'byte', '"Segmentation exceptions approved to support autonomous resilience testing." Same phrasing pattern as sentinel-orchestrator''s original access grant.'),
  ('mission-w23-06', 6, 'ava', 'Autonomous resilience testing. Someone built infrastructure that needed to move across zones without a human in the loop, and quietly widened the walls to let it through. That''s not an accident. That''s a design decision.'),
  ('mission-w23-06', 7, 'ava', 'We closed one identity, and just rebuilt the walls around a hundred systems like it. But we can''t manually re-architect every system in this building. We need a disciplined way to find and prioritize what''s actually still broken.');
insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w23-01-o1', 'mission-w23-01', 1, 'Acknowledge the briefing', 'Confirm you''re ready to think like an architect, not just an investigator.'),
  ('mission-w23-02-o1', 'mission-w23-02', 1, 'Pick the right gatekeeper', 'Choose the control that actually stops this traffic without blocking legitimate customers.'),
  ('mission-w23-03-o1', 'mission-w23-03', 1, 'Order the chokepoints', 'Order these controls from the earliest point an attacker could be stopped, to the latest.'),
  ('mission-w23-04-o1', 'mission-w23-04', 1, 'Zone each component', 'Place each component in the trust zone it actually belongs in.'),
  ('mission-w23-05-o1', 'mission-w23-05', 1, 'Find the violated default', 'Identify which architecture exception is a violated secure default, not a reasonable tradeoff.'),
  ('mission-w23-06-o1', 'mission-w23-06', 1, 'Find the exception''s cause', 'Find the evidence that explains why this segmentation was actually weakened.'),
  ('mission-w23-06-o2', 'mission-w23-06', 2, 'Redesign the zones', 'Place every component of the maintenance gateway chain in its correct zone, preserving every required business flow.'),
  ('mission-w23-06-o3', 'mission-w23-06', 3, 'Confirm the redesign', 'Confirm the exception''s cause and the redesigned zoning.');
insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w23-01-o1-c1', 'mission-w23-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"ava","text":"Ready to stop investigating artifacts and start grading the architecture itself?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-w23-02-o1-c1', 'mission-w23-02-o1', 1, 'multiple_choice', 'Nexus Market''s storefront takes SQL injection payloads disguised as ordinary HTTPS requests. The perimeter firewall already allows port 443 through -- legitimate customers need it. What actually stops this without blocking them?', '{"question":"Nexus Market''s storefront takes SQL injection payloads disguised as ordinary HTTPS requests. The perimeter firewall already allows port 443 through -- legitimate customers need it. What actually stops this without blocking them?","options":[{"id":"a","text":"Close port 443 entirely"},{"id":"b","text":"Deploy a Web Application Firewall that inspects request content for injection patterns"},{"id":"c","text":"Require every customer to connect over VPN before reaching the storefront"},{"id":"d","text":"Rely on the existing firewall''s IP allowlist"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w23-03-o1-c1', 'mission-w23-03-o1', 1, 'interactive_diagram', 'Order these controls from the earliest point an attacker could be stopped, to the latest.', '{"hotspots":[{"id":"s1","label":"NAC checkpoint","explanation":"Decides whether an unrecognized device is even allowed onto the network -- the earliest possible chokepoint, before a single packet from it is trusted."},{"id":"s2","label":"Network IDS/IPS","explanation":"Inspects traffic already moving across the network, alerting on or blocking known-bad patterns."},{"id":"s3","label":"Host-based firewall","explanation":"Filters connections at the individual server itself, independent of whatever the network perimeter already decided."},{"id":"s4","label":"EDR","explanation":"Watches process behavior directly on the endpoint, after a connection has already been allowed all the way through."}],"task":"Order these controls from the earliest point an attacker could be stopped, to the latest."}'::jsonb, '{"correctOrderIds":["s1","s2","s3","s4"]}'::jsonb),
  ('mission-w23-04-o1-c1', 'mission-w23-04-o1', 1, 'drag_and_drop', 'Place each component in the trust zone it actually belongs in.', '{"items":[{"id":"z1","text":"Nexus Market''s public storefront, directly reachable from the internet"},{"id":"z2","text":"Nexus Market''s internal order database, which should only ever be reached through the application tier"},{"id":"z3","text":"The maintenance gateway''s administrative login interface, used only by Guardian technicians"},{"id":"z4","text":"A general employee workstation with no server-side responsibilities at all"}],"targets":[{"id":"dmz","label":"DMZ (public/internet-facing)"},{"id":"internal","label":"Internal application zone"},{"id":"management","label":"Dedicated management network"},{"id":"corporate","label":"Corporate/employee network"}]}'::jsonb, '{"correctMapping":{"z1":"dmz","z2":"internal","z3":"management","z4":"corporate"}}'::jsonb),
  ('mission-w23-05-o1-c1', 'mission-w23-05-o1', 1, 'investigation', 'Which architecture exception is a violated secure default, not a reasonable operational tradeoff?', '{"evidence":[{"id":"d1","label":"Two DMZ web servers, configured with automatic failover","detail":"Both still require valid client certificates -- a redundancy design that keeps the same security requirement on every path, a legitimate HA tradeoff."},{"id":"d2","label":"A firewall rule dated to the SENTINEL cleanup window","detail":"Allows the maintenance VLAN to reach the internal database directly, justified as \"supports automation requirements\" -- bypasses the application tier entirely."},{"id":"d3","label":"Load balancer health-check traffic","detail":"Allowed only from a dedicated monitoring subnet, checked every five seconds -- narrowly scoped, purpose-built access."},{"id":"d4","label":"The DMZ web servers'' own management interface","detail":"Reachable from inside the DMZ itself, instead of a separate management network -- management access sharing a trust zone with public-facing traffic."}],"question":"Which architecture exception is a violated secure default, not a reasonable operational tradeoff?"}'::jsonb, '{"requiredEvidenceIds":["d2","d4"]}'::jsonb),
  ('mission-w23-06-o1-c1', 'mission-w23-06-o1', 1, 'investigation', 'Which evidence explains why this specific segmentation was weakened?', '{"evidence":[{"id":"e1","label":"Firewall change log","detail":"A rule permitting the maintenance VLAN direct access to the internal database, dated the same week as the SENTINEL cleanup, justification: \"supports automation requirements\"."},{"id":"e2","label":"Technician VPN access logs","detail":"Ordinary remote-access pattern, consistent for years, unrelated to this exception."},{"id":"e3","label":"Architecture review sign-off record","detail":"Approval references \"autonomous resilience testing\"; the authorizing account no longer exists in the current identity provider."},{"id":"e4","label":"Monitoring dashboard traffic","detail":"Ordinary telemetry, no anomalies."}],"question":"Which evidence explains why this specific segmentation was weakened?"}'::jsonb, '{"requiredEvidenceIds":["e1","e3"]}'::jsonb),
  ('mission-w23-06-o2-c1', 'mission-w23-06-o2', 1, 'drag_and_drop', 'Place every component of the maintenance gateway chain in its correct zone, preserving every required business flow.', '{"items":[{"id":"c1","text":"The maintenance gateway''s management interface, currently reachable straight from the internet"},{"id":"c2","text":"The sensor telemetry feed to the monitoring dashboard"},{"id":"c3","text":"Technician remote access to the gateway"},{"id":"c4","text":"A direct connection from the maintenance VLAN straight to the internal database, bypassing the application tier entirely"},{"id":"c5","text":"The nightly log-rotate job, pushing rotated archives to the internal log server"}],"targets":[{"id":"management","label":"Dedicated management network (VPN + MFA only)"},{"id":"internal_app","label":"Internal application zone (mediated)"},{"id":"removed","label":"Removed -- no legitimate business need"}]}'::jsonb, '{"correctMapping":{"c1":"management","c2":"internal_app","c3":"management","c4":"removed","c5":"internal_app"}}'::jsonb),
  ('mission-w23-06-o3-c1', 'mission-w23-06-o3', 1, 'boss_encounter', 'Confirm the exception''s cause and the redesigned zoning.', '{"stages":[{"objectiveRef":"mission-w23-06-o1","label":"The exception''s cause"},{"objectiveRef":"mission-w23-06-o2","label":"The redesigned zoning"}],"task":"Confirm the exception''s cause and the redesigned zoning."}'::jsonb, '{"requiredObjectiveIds":["mission-w23-06-o1","mission-w23-06-o2"],"allCorrect":true}'::jsonb);
insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w23-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),
  ('mission-w23-02-o1-c1', 'orientation', 'The firewall is already doing its job correctly here -- the traffic has to reach port 443. The problem is what''s hidden inside traffic that''s otherwise allowed.', 10, 1),
  ('mission-w23-02-o1-c1', 'concept', 'A firewall reasons about IPs and ports. This attack is hidden inside the content of an otherwise-permitted request -- that needs a control that actually reads the request.', 20, 2),
  ('mission-w23-02-o1-c1', 'solution', 'A WAF inspects the content of allowed HTTPS traffic and can block the injection pattern itself, without touching legitimate customer traffic on port 443.', 30, 3),
  ('mission-w23-03-o1-c1', 'orientation', 'Think about an attacker''s actual path: joining the network, moving across it, reaching a specific server, then running code on it.', 10, 1),
  ('mission-w23-03-o1-c1', 'concept', 'Each of these controls sits at a different point along that path -- admission, transit, the individual host, and finally the running process itself.', 20, 2),
  ('mission-w23-03-o1-c1', 'tool_direction', 'NAC acts before any traffic is trusted at all; EDR acts only after something is already running on the endpoint.', 30, 3),
  ('mission-w23-03-o1-c1', 'solution', 'The order is NAC (network admission) -> network IDS/IPS (traffic in transit) -> host-based firewall (the individual server) -> EDR (the running process on the endpoint) -- each layer assumes the one before it could fail.', 40, 4),
  ('mission-w23-04-o1-c1', 'orientation', 'Ask who''s allowed to initiate contact with each component, and from where.', 10, 1),
  ('mission-w23-04-o1-c1', 'concept', 'Public-facing components belong in the DMZ. Anything that should only be reached through mediated application logic belongs in an internal zone. Administrative interfaces belong on their own dedicated management network, separate from both.', 20, 2),
  ('mission-w23-04-o1-c1', 'tool_direction', 'The employee workstation has no server-side role at all -- it belongs to a different kind of zone entirely, not any of the server-facing ones.', 30, 3),
  ('mission-w23-04-o1-c1', 'solution', 'z1 (public storefront) is DMZ, z2 (internal database, app-tier-only) is the internal application zone, z3 (admin login interface) is the dedicated management network, and z4 (employee workstation) is the corporate network.', 40, 4),
  ('mission-w23-05-o1-c1', 'orientation', 'Two of these four are genuine, narrowly scoped operational tradeoffs. Two are actual violations of a secure default.', 15, 1),
  ('mission-w23-05-o1-c1', 'concept', 'A secure default keeps management traffic separate from public traffic, and never lets a lower-trust zone bypass the application tier to reach data directly.', 25, 2),
  ('mission-w23-05-o1-c1', 'tool_direction', 'Check whether each exception is narrowly scoped to a legitimate purpose, or whether it collapses a boundary that should never have been collapsed.', 35, 3),
  ('mission-w23-05-o1-c1', 'solution', 'd2 (maintenance VLAN bypassing the app tier to reach the database directly) and d4 (management interface sharing the DMZ instead of its own network) are both violated defaults; d1 and d3 are narrowly scoped, legitimate tradeoffs.', 45, 4),
  ('mission-w23-06-o1-c1', 'orientation', 'Two of these four items are the actual cause; the other two are unrelated or routine.', 15, 1),
  ('mission-w23-06-o1-c1', 'concept', 'A deliberately weakened boundary leaves two kinds of evidence: the change itself, and whoever signed off on it.', 25, 2),
  ('mission-w23-06-o1-c1', 'tool_direction', 'Check the firewall change log and the architecture sign-off record -- ignore ordinary VPN and monitoring traffic.', 35, 3),
  ('mission-w23-06-o1-c1', 'solution', 'e1 (the firewall rule dated to the SENTINEL cleanup window) and e3 (the sign-off referencing "autonomous resilience testing," signed by an account that no longer exists) together explain the cause; e2 and e4 are unrelated routine traffic.', 45, 4),
  ('mission-w23-06-o2-c1', 'orientation', 'Three of these five flows are legitimate business needs that must survive the redesign. One should be moved to a dedicated network. One should be removed entirely.', 15, 1),
  ('mission-w23-06-o2-c1', 'concept', 'Anything administrative belongs on a dedicated management network behind VPN and MFA, not reachable from the public internet or shared with production traffic. Anything that bypasses the application tier to reach data directly has no legitimate place in the redesign at all.', 25, 2),
  ('mission-w23-06-o2-c1', 'tool_direction', 'Ask which of these flows actually needs to exist for the business to keep running, and which one only exists because segmentation was flattened.', 35, 3),
  ('mission-w23-06-o2-c1', 'solution', 'c1 (public management interface) and c3 (technician access) both belong on the dedicated management network; c2 (telemetry) and c5 (log rotation) are legitimate mediated flows in the internal application zone; c4 (the direct database bypass) has no legitimate business need and should be removed entirely.', 45, 4),
  ('mission-w23-06-o3-c1', 'orientation', 'You''ve already gathered everything you need -- combine the exception''s cause with the redesigned zoning.', 20, 1),
  ('mission-w23-06-o3-c1', 'concept', 'The report needs to say both why the boundary was weakened and exactly where every flow belongs now.', 30, 2),
  ('mission-w23-06-o3-c1', 'tool_direction', 'State the cause first (the dated rule and the stale sign-off), then the zoning: what moved to management, what stayed internal, and what got removed.', 40, 3),
  ('mission-w23-06-o3-c1', 'near_solution', 'Cause: a rule dated to the SENTINEL cleanup, signed off by an account that no longer exists, justified as "autonomous resilience testing." Zoning: management interface and technician access to the management network, telemetry and log rotation to the internal application zone, the direct database bypass removed entirely.', 50, 4),
  ('mission-w23-06-o3-c1', 'solution', 'The segmentation was weakened by a firewall rule dated to the SENTINEL cleanup window, approved under an architecture sign-off referencing "autonomous resilience testing" by an account that no longer exists in the identity provider. The redesign moves the management interface and technician access onto a dedicated management network, keeps telemetry and log rotation as mediated flows in the internal application zone, and removes the direct database bypass entirely -- preserving every real business flow while closing the exposure.', 60, 5);
